/** The licence overview: this app's licence and terms, then the third-party list. */
@Composable
internal fun LicensesView(onOpenText: (LicenseText) -> Unit) {
    val uri = LocalUriHandler.current
    SettingsForm {
        item {
            SettingsSection("This App", footer = APP_LICENSE_FOOTER) {
                SettingRow(GPL3.title, "GPL-3.0", onClick = { onOpenText(GPL3) })
                SettingRow("Source code", APP_SOURCE_URL, onClick = { runCatching { uri.openUri(APP_SOURCE_URL) } })
            }
        }
        item {
            SettingsSection("Additional Terms (GPL-3.0 §7)") {
                ADDITIONAL_TERMS.forEachIndexed { i, t -> FormCaption("${i + 1}. $t") }
            }
        }
        item {
            SettingsSection("Third-Party Components") {
                THIRD_PARTY.forEach { c ->
                    SettingRow(
                        c.name,
                        c.license,
                        onClick = { if (c.text != null) onOpenText(c.text) else runCatching { uri.openUri(c.url) } }
                    )
                }
            }
        }
        item {
            SettingsSection("Sources") {
                THIRD_PARTY.distinctBy { it.url }.forEach { c ->
                    SettingRow(c.url, null, onClick = { runCatching { uri.openUri(c.url) } })
                }
            }
        }
    }
}

/** A bundled licence text, line by line (rust-crates.txt is ~220 kB). */
@Composable
internal fun LicenseTextView(text: LicenseText, onBack: () -> Unit) {
    val context = LocalContext.current
    val lines by produceState<List<String>?>(null, text.asset) {
        value = withContext(Dispatchers.IO) {
            runCatching { context.assets.open("licenses/${text.asset}").bufferedReader().use { it.readLines() } }
                .getOrElse { listOf("(${text.asset} is missing from this build)") }
        }
    }
    LazyColumn(Modifier.fillMaxWidth(), contentPadding = PaddingValues(16.dp)) {
        item {
            TextButton(onClick = onBack) { Text("‹ Licences") }
            Text(text.title, style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(vertical = 8.dp))
        }
        items(lines.orEmpty()) { line ->
            Text(line, fontFamily = FontFamily.Monospace, fontSize = 11.sp, lineHeight = 14.sp)
        }
    }
}
